public class METVendAutoGeneratePaymController extends SysOperationServiceController
{
}

Method.Source:
    /// <summary>
    /// MPJ_13564_AutoGeneratePaym
    /// Caption visible
    /// </summary>
    protected void new()
    {
        super();

        this.parmClassName(classStr(METVendAutoGeneratePaymService));
        this.parmMethodName(methodStr(METVendAutoGeneratePaymService, processOperation));
        this.parmExecutionMode(SysOperationExecutionMode::Synchronous);
        this.parmDialogCaption("@MET:VendAutoGeneratePaymGenerate");
    }

/// <summary>
/// MPJ_13564_AutoGeneratePaym
/// Automatically populates the batch text required by user before submitting to batch
/// </summary>
/// <returns>caption</returns>
public ClassDescription caption()
{
    return "@MET:VendAutoGeneratePaymGenerate";
}

    /// <summary>
    /// MPJ_13564_AutoGeneratePaym
    /// Main method required to run the opration
    /// </summary>
    /// <param name = "args">Args</param>
    public static void main(Args args)
    {
        METVendAutoGeneratePaymController controller;

        controller = new METVendAutoGeneratePaymController();
        controller.parmArgs(args);

        controller.startOperation();
        
    }

/// <summary>
/// MPJ_2864 - kscerri - 22/03/2021
/// BP to have a constructor for new controller.
/// </summary>
/// <returns>Controller instance</returns>
public static METVendAutoGeneratePaymController construct()
{
    return new METVendAutoGeneratePaymController();
}
